"""Generate RESULTS.md: every number the paper uses, each with the results/ file(s) it was computed from.
Run after the other analyses.  Nothing here is typed by hand."""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from analysis.common import *


def rel(p):
    return os.path.relpath(p, ROOT).replace("\\", "/")


def src(method, tier, target, split="test"):
    return f"results/raw/{method}__{tier}__s*__{target}__{split}.json"


def main():
    L = ["# RESULTS", "",
         "Generated by `python -m analysis.results_md`; every value is read from the file in the *Source* column.",
         "Learned methods: mean +/- sample SD over seeds [95% bootstrap CI of seed means]; each seed value is the mean over",
         "20 test starts. Controllers are deterministic single runs.", ""]

    ref = os.path.join(ROOT, "tests", "reference_values.json")
    if os.path.exists(ref):
        L += ["## Regression reference (CPU, 1 thread)", "", "| Key | Coverage | SD | Complete | Return | Steps |", "|---|---|---|---|---|---|"]
        for k, v in json.load(open(ref)).items():
            L.append(f"| {k} | {v['coverage_mean']:.2f} | {v['coverage_sd']:.2f} | {v['n_complete']}/20 | "
                     f"{v['ret_mean']:.1f} | {v['steps_mean']:.0f} | ")
        L += ["", "Source: `tests/reference_values.json`", ""]

    for target in ("path1", "path2", "path3"):
        L += [f"## Main results on {target} (test starts)", "",
              "| Method | Seeds | Coverage % | Completed | Return | Steps | Source |", "|---|---|---|---|---|---|---|"]
        for sel in ("ppo_final", "ppo_valsel"):
            for tier in TIER_ORDER:
                rs = load(sel, tier, target)
                if rs:
                    a = agg(rs, "coverage_mean")
                    L.append(f"| {sel} {tier} | {a['n']} | {a['mean']:.2f} +/- {a['sd']:.2f} [{a['lo']:.2f}, {a['hi']:.2f}] | "
                             f"{sum(r['summary']['n_complete'] for r in rs)}/{20 * len(rs)} | "
                             f"{agg(rs, 'ret_mean')['mean']:.1f} | {agg(rs, 'steps_mean')['mean']:.0f} | `{src(sel, tier, target)}` |")
        names = sorted({os.path.basename(f).split("__")[0] for f in glob.glob(os.path.join(RAW, "*__none__*"))})
        for n in names:
            for r in load(n, "none", target):
                S = r["summary"]
                L.append(f"| {n} | 1 | {S['coverage_mean']:.2f} | {S['n_complete']}/20 | {S['ret_mean']:.1f} | "
                         f"{S['steps_mean']:.0f} | `{src(n, 'none', target)}` |")
        L.append("")

    for name, title in (("sweep.json", "Speed sweep (path1 validation starts) and selected speeds"),
                        ("slow_tracer.json", "Slow-tracer test"),
                        ("metric_sensitivity.json", "Metric sensitivity (coverage % per rho)"),
                        ("mechanism.json", "Mechanism analysis")):
        p = os.path.join(ROOT, "results", name)
        if os.path.exists(p):
            L += [f"## {title}", "", f"Source: `results/{name}` (values below copied verbatim)", "", "```json",
                  json.dumps(json.load(open(p)), indent=1)[:60000], "```", ""]
    open(os.path.join(ROOT, "RESULTS.md"), "w", encoding="utf-8").write("\n".join(L))
    print("wrote RESULTS.md")


if __name__ == "__main__":
    main()
